// These scripts execute only in Electron's isolated world. Inputs are opaque IDs
// generated by the main process, never selectors or page-provided code.
export const SNAPSHOT_SCRIPT = `(() => {
  const viewport = () => ({ width: Math.min(innerWidth, document.documentElement.clientWidth), height: Math.min(innerHeight, document.documentElement.clientHeight) });
  const bounds = viewport();
  if (bounds.width <= 0 || bounds.height <= 0) { delete globalThis.__vibelutionBrowserSnapshot; return { viewportUnavailable: true }; }
  const clean = (s, n) => String(s || '').replace(/\\s+/g, ' ').trim().slice(0, n);
  const visible = e => { const r = e.getBoundingClientRect(), v = viewport(); if (!e.isConnected || v.width <= 0 || v.height <= 0 || r.width <= 0 || r.height <= 0 || r.bottom <= 0 || r.right <= 0 || r.top >= v.height || r.left >= v.width || e.closest('[inert],[aria-hidden="true"]')) return false; for (let p = e; p; p = p.parentElement) { const s = getComputedStyle(p); if (s.visibility !== 'visible' || s.display === 'none' || Number(s.opacity) <= 0) return false; } return true; };
  const role = e => e.getAttribute('role') || (e.tagName === 'A' ? 'link' : e.tagName === 'BUTTON' ? 'button' : e.tagName === 'SELECT' ? 'combobox' : e.tagName === 'TEXTAREA' ? 'textbox' : e.tagName === 'INPUT' ? (['checkbox','radio'].includes(e.type) ? e.type : ['button','submit','reset'].includes(e.type) ? 'button' : 'textbox') : '');
  const name = e => clean(e.getAttribute('aria-label') || e.labels?.[0]?.innerText || e.getAttribute('title') || e.innerText || e.getAttribute('placeholder') || (['button','submit','reset'].includes(e.type) ? e.value : ''), 160);
  const candidates = document.querySelectorAll('a[href],button,input,textarea,select,[role="button"],[role="link"],[role="textbox"],[role="checkbox"],[role="radio"]');
  const refs = new Map(), elements = [];
  for (const e of candidates) {
    if (elements.length >= 80) break;
    if (!visible(e) || e.disabled || e.getAttribute('aria-disabled') === 'true' || (e.tagName === 'INPUT' && ['password','hidden','file'].includes(e.type))) continue;
    const r = role(e), n = name(e), ref = String(elements.length + 1);
    refs.set(ref, { e, r, n }); elements.push({ ref, role: r, name: n });
  }
  globalThis.__vibelutionBrowserSnapshot = { refs, visible, role, name, viewport };
  const text = clean(document.body?.innerText, 8000);
  return { text, elements };
})()`;

export function snapshotScript(snapshotId: string): string {
  return `(() => { const result = ${SNAPSHOT_SCRIPT}; if (!result.viewportUnavailable) globalThis.__vibelutionBrowserSnapshot.token = ${JSON.stringify(snapshotId)}; return result; })()`;
}

export function targetScript(ref: string, operation: "click" | "fill" | "preview", value = "", snapshotId = ""): string {
  // ref is checked as a numeric index by the main process before reaching here.
  return `(() => {
    const s = globalThis.__vibelutionBrowserSnapshot, item = s?.refs.get(${JSON.stringify(ref)}), e = item?.e;
    if ((${JSON.stringify(snapshotId)} && s?.token !== ${JSON.stringify(snapshotId)}) || !e || !s.visible(e) || e.disabled || e.getAttribute('aria-disabled') === 'true' || s.role(e) !== item.r || s.name(e) !== item.n) return null;
    if (e.tagName === 'INPUT' && ['password','hidden','file'].includes(e.type)) return null;
    const r = e.getBoundingClientRect(), v = s.viewport(), x = (Math.max(0, r.left) + Math.min(v.width, r.right)) / 2, y = (Math.max(0, r.top) + Math.min(v.height, r.bottom)) / 2;
    const top = document.elementFromPoint(x, y);
    if (!top || !(e === top || e.contains(top))) return null;
    if (${JSON.stringify(operation)} === 'fill') {
      if (!(e instanceof HTMLTextAreaElement || (e instanceof HTMLInputElement && ['text','search','url','email','tel'].includes(e.type))) || e.readOnly) return null;
      const value = ${JSON.stringify(value)}, parent = e.parentNode, next = e.nextSibling;
      const proto = e instanceof HTMLTextAreaElement ? HTMLTextAreaElement.prototype : HTMLInputElement.prototype;
      const descriptor = Object.getOwnPropertyDescriptor(proto, "value"), setter = descriptor?.set, getter = descriptor?.get;
      if (!setter || !getter) return null;
      setter.call(e, value);
      const inputAccepted = e.dispatchEvent(new Event("input", { bubbles: true, cancelable: true }));
      const changeAccepted = e.dispatchEvent(new Event("change", { bubbles: true, cancelable: true }));
      if (!e.isConnected || e.parentNode !== parent || e.nextSibling !== next || !s.visible(e) || s.role(e) !== item.r || s.name(e) !== item.n || (e instanceof HTMLInputElement && !["text","search","url","email","tel"].includes(e.type))) return { filled: false };
      return { filled: inputAccepted && changeAccepted && getter.call(e) === value };
    }
    if (${JSON.stringify(operation)} === "click") {
      if (!(e instanceof HTMLElement)) return null;
      // A new-window anchor is followed directly in the owned view. No popup or page-provided URL is accepted from the caller.
      if (e instanceof HTMLAnchorElement && e.target.toLowerCase() === "_blank" && e.hasAttribute("href")) {
        if (/[\\x00-\\x1f\\x7f]/.test(e.getAttribute("href") || "")) return { invalidUrl: true };
        return { navigateUrl: e.href };
      }
      HTMLElement.prototype.click.call(e);
      return { clicked: true };
    }
    return { role: String(item.r).slice(0, 40), name: item.n };
  })()`;
}
